CREATE TABLE assets (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 symbol VARCHAR(15) NOT NULL UNIQUE CHECK (symbol ~ '^[A-Z][A-Z0-9.-]{0,14}$'),
 company_name VARCHAR(160) NOT NULL, exchange VARCHAR(40) NOT NULL,
 currency CHAR(3) NOT NULL CHECK (currency ~ '^[A-Z]{3}$'),
 asset_type VARCHAR(20) NOT NULL DEFAULT 'STOCK', created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE historical_prices (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 asset_id BIGINT NOT NULL REFERENCES assets(id), trading_date DATE NOT NULL,
 open NUMERIC(20,6) NOT NULL CHECK(open>0), high NUMERIC(20,6) NOT NULL,
 low NUMERIC(20,6) NOT NULL CHECK(low>0), close NUMERIC(20,6) NOT NULL CHECK(close>0),
 adjusted_close NUMERIC(20,6), volume BIGINT NOT NULL CHECK(volume>=0),
 provider VARCHAR(60) NOT NULL, source_timestamp TIMESTAMPTZ,
 ingested_at TIMESTAMPTZ NOT NULL DEFAULT now(),
 UNIQUE(asset_id,trading_date,provider),
 CHECK(high>=low AND high>=open AND high>=close AND low<=open AND low<=close)
);
CREATE INDEX idx_prices_asset_date ON historical_prices(asset_id,trading_date DESC);
CREATE TABLE watchlists (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE watchlist_items (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,watchlist_id BIGINT NOT NULL REFERENCES watchlists(id) ON DELETE CASCADE,asset_id BIGINT NOT NULL REFERENCES assets(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(watchlist_id,asset_id));
CREATE TABLE portfolios (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(100) NOT NULL,base_currency CHAR(3) NOT NULL CHECK(base_currency ~ '^[A-Z]{3}$'),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE portfolio_holdings (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,portfolio_id BIGINT NOT NULL REFERENCES portfolios(id) ON DELETE CASCADE,asset_id BIGINT NOT NULL REFERENCES assets(id),quantity NUMERIC(20,6) NOT NULL CHECK(quantity>0),average_purchase_price NUMERIC(20,6) NOT NULL CHECK(average_purchase_price>0),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(portfolio_id,asset_id));
CREATE TABLE ingestion_runs (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,asset_id BIGINT NOT NULL REFERENCES assets(id),provider VARCHAR(60) NOT NULL,status VARCHAR(20) NOT NULL CHECK(status IN ('RUNNING','SUCCESS','FAILED')),started_at TIMESTAMPTZ NOT NULL DEFAULT now(),completed_at TIMESTAMPTZ,records_inserted INT NOT NULL DEFAULT 0 CHECK(records_inserted>=0),error_message VARCHAR(500));
CREATE INDEX idx_ingestion_started ON ingestion_runs(started_at DESC);
CREATE INDEX idx_ingestion_asset ON ingestion_runs(asset_id,started_at DESC);
CREATE TABLE model_versions (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,model_name VARCHAR(100) NOT NULL,version VARCHAR(64) NOT NULL,status VARCHAR(30) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),artifact_reference TEXT,UNIQUE(model_name,version));
CREATE TABLE model_predictions (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,model_version_id BIGINT NOT NULL REFERENCES model_versions(id),asset_id BIGINT NOT NULL REFERENCES assets(id),prediction_target_date DATE NOT NULL,predicted_value NUMERIC(20,6) NOT NULL,probability NUMERIC(9,8) CHECK(probability BETWEEN 0 AND 1),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_predictions_asset ON model_predictions(asset_id,created_at DESC);
CREATE TABLE strategies (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(100) NOT NULL,strategy_type VARCHAR(40) NOT NULL UNIQUE,configuration JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE backtest_runs (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,strategy_id BIGINT NOT NULL REFERENCES strategies(id),asset_id BIGINT NOT NULL REFERENCES assets(id),start_date DATE NOT NULL,end_date DATE NOT NULL,initial_capital NUMERIC(20,6) NOT NULL CHECK(initial_capital>0),status VARCHAR(30) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(end_date>=start_date));
CREATE TABLE backtest_results (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,backtest_run_id BIGINT NOT NULL UNIQUE REFERENCES backtest_runs(id) ON DELETE CASCADE,cumulative_return NUMERIC(20,10),sharpe_ratio NUMERIC(20,10),maximum_drawdown NUMERIC(20,10),volatility NUMERIC(20,10));
CREATE TABLE application_settings (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,setting_key VARCHAR(100) NOT NULL UNIQUE,setting_value JSONB NOT NULL,updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
